    question: "According to the passage, what is the main reason electrical devices can be dangerous in homes?\n\nRead the passage and answer the following questions:\n\nIn today’s homes, electrical devices are as ordinary as furniture. From refrigerators and washing machines to smart televisions and microwave ovens, these appliances have reshaped domestic life. However, their growing presence has also increased the risks, especially for children, whose natural curiosity often overrides caution.\n\nElectrical devices run on currents that can cause serious injury or even death if mishandled. Young children, unaware of these dangers, may put fingers or objects into sockets, pull on dangling cords, or try to open appliance panels. Such actions can lead to shocks, burns, or mechanical harm. Even low-voltage devices can be hazardous if they are defective or poorly maintained.\n\nThe responsibility for preventing accidents rests largely with adults. Simple precautions include installing socket covers, keeping cords out of reach, and unplugging appliances when not in use. More advanced measures involve using Residual Current Devices (RCDs), which automatically cut off power during faults, and ensuring that all wiring complies with safety standards. Regular inspection is equally critical, as frayed wires or exposed parts can turn everyday items into hidden threats.\n\nEducation also plays a vital role. Teaching children the “look, don’t touch” rule, explaining electrical dangers in age-appropriate terms, and supervising them around devices are effective strategies. Safety is not only about physical barriers but also about fostering awareness.\n\nUltimately, a home filled with electrical conveniences does not have to become a danger zone. With vigilant supervision, families can enjoy technology while safeguarding their youngest members.",
